// Normalizes e-signature webhook payloads from PandaDoc, DocuSign or SignWell
// into one shape. Add a new branch below if you onboard another platform.

const RETAINER_AMOUNT_CENTS  = 125000;   // $1,250.00/mo recurring retainer, in cents
const SETUP_FEE_AMOUNT_CENTS = 150000;   // $1,500.00 one-time deployment fee, in cents
const SETUP_FEE_DESCRIPTION  = 'Initial Infrastructure & AI Agent Deployment Fee (one-time)';
const RETAINER_CURRENCY     = 'usd';
const RETAINER_DESCRIPTION  = 'Monthly retainer - initial invoice';

const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  // PandaDoc posts an array of events; DocuSign posts a single object.
  const evt = Array.isArray(body) ? body[0] : body;
  if (!evt) { continue; }

  const d = evt.data ?? {};
  let provider, isCompleted, documentId, documentName, email, name, downloadUrl;
  // Where per-deal metadata and company live; SignWell nests them one deeper.
  let metaHost = d;

  // SignWell sends event as an OBJECT ({id,time,type,hash}) and wraps the
  // document in data.object -- check it first, since the PandaDoc branch is
  // the fallthrough and would otherwise swallow it.
  const isSignWell = (evt.event && typeof evt.event === 'object' && evt.event.type)
                  || (d.object && typeof d.object === 'object');

  if (isSignWell) {
    // ---- SignWell ----
    provider = 'signwell';
    const obj    = d.object ?? {};
    const type   = String(evt.event?.type ?? '').toLowerCase();
    const status = String(obj.status ?? '').toLowerCase();
    metaHost = obj;

    isCompleted  = type === 'document_completed' || status === 'completed';
    documentId   = obj.id;
    documentName = obj.name ?? `document-${documentId}`;

    const signer = (obj.recipients ?? []).find(r => String(r.status ?? '').toLowerCase() === 'completed')
                ?? (obj.recipients ?? [])[0] ?? {};
    email = signer.email;
    name  = signer.name || signer.email;

    // SignWell requires an X-Api-Key call to fetch the finished PDF.
    downloadUrl = evt.download_url
      ?? obj.completed_pdf_url
      ?? `https://www.signwell.com/api/v1/documents/${documentId}/completed_pdf/`;
  } else if (d.envelopeId || evt.envelopeId || d.envelopeSummary) {
    // ---- DocuSign Connect ----
    provider = 'docusign';
    const summary = d.envelopeSummary ?? d;
    const signer  = summary?.recipients?.signers?.[0] ?? {};
    const status  = String(summary.status ?? evt.status ?? '').toLowerCase();

    isCompleted  = status === 'completed' || String(evt.event ?? '').toLowerCase() === 'envelope-completed';
    documentId   = d.envelopeId ?? evt.envelopeId;
    documentName = summary.emailSubject ?? `envelope-${documentId}`;
    email        = signer.email;
    name         = signer.name;
    // DocuSign requires an authenticated eSignature API call to fetch the PDF.
    downloadUrl  = evt.download_url
      ?? `https://demo.docusign.net/restapi/v2.1/accounts/{{ACCOUNT_ID}}/envelopes/${documentId}/documents/combined`;
  } else {
    // ---- PandaDoc ----
    provider = 'pandadoc';
    const recipient = (d.recipients ?? []).find(r => r.has_completed) ?? (d.recipients ?? [])[0] ?? {};
    const status    = String(d.status ?? evt.status ?? '').toLowerCase();

    isCompleted  = status === 'document.completed'
                || String(evt.event ?? '').toLowerCase() === 'document_completed';
    documentId   = d.id ?? evt.id;
    documentName = d.name ?? `document-${documentId}`;
    email        = recipient.email;
    name         = [recipient.first_name, recipient.last_name].filter(Boolean).join(' ') || recipient.email;
    downloadUrl  = evt.download_url ?? `https://api.pandadoc.com/public/v1/documents/${documentId}/download`;
  }

  // Metadata overrides let the e-sign template carry per-deal commercials.
  const meta = metaHost.metadata ?? d.metadata ?? evt.metadata ?? {};

  const amountCents   = Number(meta.retainer_amount_cents ?? RETAINER_AMOUNT_CENTS);
  // Setup fee may be overridden per deal, and may be 0 to waive it entirely.
  const setupFeeCents = Number(meta.setup_fee_amount_cents ?? SETUP_FEE_AMOUNT_CENTS);

  if (isCompleted && (!Number.isInteger(amountCents) || amountCents <= 0)) {
    throw new Error(
      `RETAINER_AMOUNT_CENTS is not configured (got ${JSON.stringify(RETAINER_AMOUNT_CENTS)}). ` +
      `Set it to an integer number of cents in the "Normalize E-Signature Payload" node, ` +
      `or supply metadata.retainer_amount_cents from the e-signature template.`
    );
  }

  if (isCompleted && (!Number.isInteger(setupFeeCents) || setupFeeCents < 0)) {
    throw new Error(
      `SETUP_FEE_AMOUNT_CENTS is invalid (got ${JSON.stringify(setupFeeCents)}). ` +
      `Must be a non-negative integer number of cents. Set 0 to waive the setup fee.`
    );
  }

  if (isCompleted && !email) {
    throw new Error(`Completed ${provider} document ${documentId} has no signer email; cannot invoice.`);
  }

  out.push({
    json: {
      provider,
      is_completed: Boolean(isCompleted),
      document_id: documentId ?? null,
      document_name: documentName,
      file_name: `${String(documentName).replace(/[^A-Za-z0-9._-]+/g, '_').slice(0, 80)}.pdf`,
      client_email: email ?? null,
      client_name: name ?? null,
      client_company: meta.company ?? metaHost.company ?? d.company ?? null,
      download_url: downloadUrl,
      retainer_amount_cents: amountCents,
      setup_fee_amount_cents: setupFeeCents,
      setup_fee_description: meta.setup_fee_description ?? SETUP_FEE_DESCRIPTION,
      initial_invoice_total_cents: amountCents + setupFeeCents,
      initial_invoice_description:
        `Initial invoice - deployment fee plus first month retainer ` +
        `(${((amountCents + setupFeeCents) / 100).toFixed(2)} ${String(meta.currency ?? RETAINER_CURRENCY).toUpperCase()})`,
      retainer_currency: String(meta.currency ?? RETAINER_CURRENCY).toLowerCase(),
      retainer_description: meta.description ?? RETAINER_DESCRIPTION,
      received_at: new Date().toISOString(),
    },
  });
}

return out;

// Runs on both branches of the dedupe split.
//   New-customer path arrives as a Stripe invoiceitem object, which carries `customer`.
//   Existing-customer path arrives as the Set node output, which carries `customer_id`.
// Normalizes the two shapes and derives the correct invoice total and description,
// since an existing customer is NOT charged the one-time deployment fee again.

const norm = $('Normalize E-Signature Payload').first().json;
const currency = String(norm.retainer_currency || 'usd').toUpperCase();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const customerId = j.customer_id ?? j.customer ?? null;

  if (!customerId) {
    throw new Error(
      'Could not resolve a Stripe customer id after the dedupe branch. ' +
      `Received keys: ${Object.keys(j).join(', ')}`
    );
  }

  const isExisting = Boolean(j.is_existing_customer);
  const totalCents = isExisting
    ? norm.retainer_amount_cents
    : norm.retainer_amount_cents + norm.setup_fee_amount_cents;

  out.push({
    json: {
      customer_id: customerId,
      is_existing_customer: isExisting,
      setup_fee_charged: !isExisting,
      invoice_total_cents: totalCents,
      invoice_description: isExisting
        ? `Monthly retainer (${(totalCents / 100).toFixed(2)} ${currency})`
        : `Initial invoice - deployment fee plus first month retainer `
          + `(${(totalCents / 100).toFixed(2)} ${currency})`,
    },
  });
}

return out;

// ---------------------------------------------------------------------------
// Fail-closed HMAC verification for e-signature webhooks.
//
// REQUIRES on the n8n instance:
//   NODE_FUNCTION_ALLOW_BUILTIN=crypto      (or *)
//   ESIGN_WEBHOOK_SECRET=<shared secret from DocuSign / PandaDoc>
//   SIGNWELL_API_KEY=<SignWell API key>     (optional; falls back to the above)
//
// Supported schemes:
//   DocuSign Connect : HMAC-SHA256(raw body),          base64, header x-docusign-signature-N
//   PandaDoc         : HMAC-SHA256(raw body),          hex,    query param ?signature=
//   SignWell         : HMAC-SHA256(event.time + type), hex,    body field event.hash
//
// !! SignWell caveat: its hash covers only the event timestamp and type, NOT
// !! the request body. A valid hash therefore proves the event came from
// !! SignWell but does NOT prove the payload is unmodified, and the same hash
// !! stays valid for replays of that (time, type) pair. The downstream
// !! "Idempotency Guard" is what prevents a replayed document from being
// !! invoiced twice -- do not remove it.
//
// Any failure -- missing module, missing secret, missing or bad signature --
// throws. This node must never let an unverified payload reach Stripe.
// ---------------------------------------------------------------------------

let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  throw new Error(
    'Signature verification unavailable: the Code node cannot load "crypto". ' +
    'Set NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance and restart. ' +
    'Refusing to process an unverified payload.'
  );
}

function readEnv(name) {
  try {
    return $env[name];
  } catch (e) {
    throw new Error(
      `Cannot read $env.${name} (env access is blocked in Code nodes). ` +
      'Unset N8N_BLOCK_ENV_ACCESS_IN_NODE, or inline the secret here. ' +
      'Refusing to process an unverified payload.'
    );
  }
}

// Read both up front so a misconfigured instance fails on the env, not the scheme.
const esignSecret  = readEnv('ESIGN_WEBHOOK_SECRET');
const signwellKey  = readEnv('SIGNWELL_API_KEY') || esignSecret;

function requireSecret(value, name, scheme) {
  if (!value || String(value).trim() === '') {
    throw new Error(
      `${name} is empty or unset, so the "${scheme}" signature cannot be checked. ` +
      'Refusing to process an unverified payload.'
    );
  }
  return String(value);
}

// --- recover the exact bytes the provider signed --------------------------
let rawBuf = null;
try {
  if (typeof this !== 'undefined' && this.helpers && this.helpers.getBinaryDataBuffer) {
    rawBuf = await this.helpers.getBinaryDataBuffer(0, 'data');
  }
} catch (e) {
  rawBuf = null;
}
if (!rawBuf) {
  const bin = $input.first().binary && $input.first().binary.data;
  if (bin && bin.data) {
    rawBuf = Buffer.from(bin.data, 'base64');
  }
}
if (!rawBuf || !rawBuf.length) {
  throw new Error(
    'Raw request body unavailable. Enable "Raw Body" on the Webhook node. ' +
    'Signature cannot be verified against a re-serialised body.'
  );
}

const headers = $input.first().json.headers || {};
const query   = $input.first().json.query   || {};

function timingSafeEq(a, b) {
  const ab = Buffer.from(String(a));
  const bb = Buffer.from(String(b));
  if (ab.length !== bb.length) return false;   // length leak is not sensitive here
  return crypto.timingSafeEqual(ab, bb);
}

function hmac(secret, data, encoding) {
  return crypto.createHmac('sha256', secret).update(data).digest(encoding);
}

// SignWell carries its signature inside the body, so parse before dispatching.
// A parse failure is not fatal yet -- the raw-body schemes do not need it.
let parsed = null;
try {
  parsed = JSON.parse(rawBuf.toString('utf8'));
} catch (e) {
  parsed = null;
}
const parsedEvt   = Array.isArray(parsed) ? parsed[0] : parsed;
const signwellEvt = (parsedEvt && parsedEvt.event && typeof parsedEvt.event === 'object')
  ? parsedEvt.event
  : null;

// DocuSign rotates keys, so it may send several numbered signature headers.
const docusignSigs = Object.keys(headers)
  .filter(k => /^x-docusign-signature-\d+$/i.test(k))
  .map(k => headers[k])
  .filter(Boolean);

const pandadocSig = query.signature || headers['x-pandadoc-signature'] || null;

let scheme = null;
let verified = false;

if (docusignSigs.length > 0) {
  scheme = 'docusign';
  const secret = requireSecret(esignSecret, 'ESIGN_WEBHOOK_SECRET', scheme);
  const digestB64 = hmac(secret, rawBuf, 'base64');
  verified = docusignSigs.some(sig => timingSafeEq(sig, digestB64));
} else if (pandadocSig) {
  scheme = 'pandadoc';
  const secret = requireSecret(esignSecret, 'ESIGN_WEBHOOK_SECRET', scheme);
  // Accept either encoding; PandaDoc documents hex.
  verified = timingSafeEq(pandadocSig, hmac(secret, rawBuf, 'hex'))
          || timingSafeEq(pandadocSig, hmac(secret, rawBuf, 'base64'));
} else if (signwellEvt && signwellEvt.hash) {
  scheme = 'signwell';
  const key = requireSecret(signwellKey, 'SIGNWELL_API_KEY / ESIGN_WEBHOOK_SECRET', scheme);
  if (signwellEvt.time === undefined || signwellEvt.time === null || !signwellEvt.type) {
    throw new Error(
      'SignWell payload has event.hash but is missing event.time or event.type, ' +
      'so the signed string cannot be reconstructed. Payload rejected.'
    );
  }
  const signedString = `${signwellEvt.time}${signwellEvt.type}`;
  const expected = hmac(key, signedString, 'hex');
  verified = timingSafeEq(String(signwellEvt.hash).toLowerCase(), expected.toLowerCase());
} else {
  throw new Error(
    'No webhook signature present (looked for x-docusign-signature-N header, ' +
    '?signature= query param, and SignWell event.hash). Rejecting unsigned payload.'
  );
}

if (!verified) {
  throw new Error(
    `Webhook signature mismatch for scheme "${scheme}". Payload rejected. ` +
    'Either the shared secret is wrong or the request is forged.'
  );
}

// --- signature good: hand downstream --------------------------------------
if (parsed === null) {
  throw new Error('Signature valid but body is not JSON.');
}

return [{
  json: {
    body: parsed,
    headers,
    query,
    signature_scheme: scheme,
    signature_verified: true,
  },
}];

// ---------------------------------------------------------------------------
// Duplicate-submission guard.
//
// Keyed on provider + document_id, persisted in workflow static data so it
// survives across executions.
//
// Two-phase claim so a crashed run does not permanently block re-billing:
//   in_progress + fresh  -> duplicate (a retry is racing us) -> skip
//   in_progress + stale  -> previous run died -> reclaim and reprocess
//   completed            -> already invoiced -> skip
//
// "Mark Document Processed" flips the claim to completed after the invoice
// is actually sent. Stripe Idempotency-Key headers on the mutating calls are
// the second line of defence for races this ledger cannot see.
// ---------------------------------------------------------------------------

const CLAIM_TTL_MS  = 15 * 60 * 1000;             // assume a run older than this died
const LEDGER_TTL_MS = 90 * 24 * 60 * 60 * 1000;   // forget documents after 90 days
const MAX_ENTRIES   = 5000;                       // hard cap on ledger growth

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedDocuments || typeof staticData.processedDocuments !== 'object') {
  staticData.processedDocuments = {};
}
const ledger = staticData.processedDocuments;
const now = Date.now();

// prune by age
for (const k of Object.keys(ledger)) {
  const entry = ledger[k];
  if (!entry || typeof entry.ts !== 'number' || (now - entry.ts) > LEDGER_TTL_MS) {
    delete ledger[k];
  }
}
// prune by size, oldest first
const keys = Object.keys(ledger);
if (keys.length > MAX_ENTRIES) {
  keys.sort((a, b) => ledger[a].ts - ledger[b].ts)
      .slice(0, keys.length - MAX_ENTRIES)
      .forEach(k => delete ledger[k]);
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  if (!j.document_id) {
    throw new Error(
      'Completed document has no document_id; cannot guarantee single billing. ' +
      'Refusing to proceed rather than risk a duplicate invoice.'
    );
  }

  const key  = `${j.provider}:${j.document_id}`;
  const prev = ledger[key];

  let isDuplicate = false;
  let reason = 'new_document';

  if (prev && prev.status === 'completed') {
    isDuplicate = true;
    reason = 'already_invoiced';
  } else if (prev && prev.status === 'in_progress' && (now - prev.ts) < CLAIM_TTL_MS) {
    isDuplicate = true;
    reason = 'in_flight';
  } else if (prev && prev.status === 'in_progress') {
    reason = 'stale_claim_reclaimed';
  }

  if (!isDuplicate) {
    ledger[key] = {
      status: 'in_progress',
      ts: now,
      attempts: ((prev && prev.attempts) || 0) + 1,
      client_email: j.client_email || null,
    };
  }

  out.push({
    json: {
      ...j,
      idempotency_key: key,
      // Safe inside a Stripe Idempotency-Key header (max 255 chars, opaque).
      stripe_idempotency_base: `msa-${j.provider}-${j.document_id}`.slice(0, 200),
      is_duplicate: isDuplicate,
      duplicate_reason: reason,
      previous_invoice_id: (prev && prev.invoice_id) || null,
    },
  });
}

return out;

// Flip the claim from in_progress to completed now that the invoice is sent.
// Until this runs, a crashed execution leaves a claim that expires after
// CLAIM_TTL_MS so the document can be retried rather than silently lost.

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedDocuments || typeof staticData.processedDocuments !== 'object') {
  staticData.processedDocuments = {};
}

const guard = $('Idempotency Guard').first().json;
const key = guard.idempotency_key;
const prev = staticData.processedDocuments[key] || {};

const out = [];
for (const item of $input.all()) {
  const invoiceId = item.json.id || null;

  staticData.processedDocuments[key] = {
    status: 'completed',
    ts: Date.now(),
    attempts: prev.attempts || 1,
    invoice_id: invoiceId,
    client_email: guard.client_email || null,
    document_id: guard.document_id || null,
  };

  out.push({
    json: {
      ...item.json,
      idempotency_key: key,
      billing_committed: true,
    },
  });
}

return out;

// ---------------------------------------------------------------------------
// Derive the per-client Drive folder name from the normalized payload and
// build a safe Drive v3 search query.
//
// The name is client-controlled (it arrives via e-sign template metadata), so
// it is sanitised before use and escaped before being interpolated into the
// query string. An unescaped apostrophe would break the query outright; a
// crafted one could alter its meaning.
// ---------------------------------------------------------------------------

const PARENT_FOLDER_ID = 'YOUR_DRIVE_FOLDER_ID';
const FOLDER_MIME = 'application/vnd.google-apps.folder';
const MAX_NAME_LEN = 120;

function sanitizeFolderName(raw) {
  return String(raw)
    .replace(/[\u0000-\u001F\u007F]/g, ' ')  // strip control characters
    .replace(/[\\/]/g, '-')                  // path separators confuse Drive UIs
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, MAX_NAME_LEN)
    .trim();
}

// Drive v3 query literals are single-quoted: escape backslash then quote.
function escapeDriveQueryValue(value) {
  return String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  // Company is the routing key; fall back to signer name, then email local part.
  const rawCandidate =
    j.client_company ||
    j.client_name ||
    (j.client_email ? String(j.client_email).split('@')[0] : null);

  if (!rawCandidate || !String(rawCandidate).trim()) {
    throw new Error(
      `Cannot derive a client folder name for document ${j.document_id}: ` +
      'client_company, client_name and client_email are all empty. ' +
      'Refusing to file a signed MSA into an unnamed folder.'
    );
  }

  const folderName = sanitizeFolderName(rawCandidate);
  if (!folderName) {
    throw new Error(
      `Client folder name for document ${j.document_id} is empty after ` +
      `sanitising ${JSON.stringify(String(rawCandidate).slice(0, 80))}.`
    );
  }

  const query =
    `'${escapeDriveQueryValue(PARENT_FOLDER_ID)}' in parents and ` +
    `name = '${escapeDriveQueryValue(folderName)}' and ` +
    `mimeType = '${FOLDER_MIME}' and trashed = false`;

  out.push({
    json: {
      ...j,
      client_folder_name: folderName,
      client_folder_name_source: j.client_company
        ? 'company'
        : (j.client_name ? 'signer_name' : 'email_local_part'),
      client_folder_parent_id: PARENT_FOLDER_ID,
      drive_search_query: query,
    },
  });
}

return out;

// Normalises the two branch shapes into a single folder id.
//   existing path -> Set node output: { client_folder_id, folder_was_created }
//   created path  -> Drive file resource: { id, name, parents }

const named = $('Resolve Client Folder Name').first().json;
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const wasCreated = j.client_folder_id === undefined;
  const folderId = j.client_folder_id ?? j.id ?? null;

  if (!folderId) {
    throw new Error(
      'Could not resolve a Drive folder id after the lookup-or-create branch. ' +
      `Received keys: ${Object.keys(j).join(', ')}`
    );
  }

  out.push({
    json: {
      client_folder_id: folderId,
      client_folder_name: named.client_folder_name,
      client_folder_parent_id: named.client_folder_parent_id,
      folder_was_created: wasCreated,
    },
  });
}

return out;
